ReplacementContent:
"                        <button
                           type="button"
                           disabled={isCheckingOut}
                           onClick={() => {
                              if (isCheckingOut) return;
                              const checkMethod = isSplitPayment ? 'SPLIT' : selectedPaymentMode;
                              handleCheckout('SETTLE', checkMethod, paymentReferenceNo, tipAmount, isDuePayment);
                              setIsPaymentModalOpen(false);
                           }}
                           className={`px-8 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-[10px] font-black uppercase tracking-wider shadow-lg active:scale-95 transition-all ${isCheckingOut ? 'opacity-50 cursor-not-allowed' : ''}`}
                        >
                           {isCheckingOut ? 'Settling...' : 'Settle Bill'}
                        </button>"

